// v23.xx (spr6), HIS ORDER (2026-10-12): "improve the sprites of all characters, bots, etc", gritty and grounded like ARC
// Raiders. The sprite program, MACHINES A, build 5: WEAK POINTS ARE SOCKETS. A weak point was a bright coloured disc with a
// glow two and a half times its size, so the brightest thing on a Sentry, a Warden or a Pillbox was its weak point and at play
// size a Warden read as two coloured wheels. The eye is the face and must win. Each opening is now a recessed socket: a dark
// ring, a thin ring in its own colour (orange vent, blue optic, as before) and a small core, held at about a third of full
// strength and below the eye, gently pulsing. When it is hot (the overheat its hit buys) it glows full, with a baked glow
// disc round it, so the window to punish is unmistakable. Where the openings are, which way they turn, and what a hit on one
// does are unchanged; only how they are drawn.
function sprWeakPts(e){
  var WL=weakOf(e), wk, WW, p, hot, pls, a, gd, t=(typeof G!=='undefined'&&G)?(G.t||0):0;
  if(!WL) return 0;
  for(wk=0;wk<WL.length;wk++){
    WW=WL[wk]; p=weakPos(e,WW);
    hot=(WW.eff==='overheat'&&e.overheat>0);
    pls=0.62+0.38*Math.sin(t*3.1+wk*2.1+e.x*0.01);
    if(hot){
      gd=sprGlow(WW.c);
      if(gd){ wc.save(); wc.globalCompositeOperation='lighter'; wc.globalAlpha=1; wc.drawImage(gd,p.x-WW.rad*2.6,p.y-WW.rad*2.6,WW.rad*5.2,WW.rad*5.2); wc.restore(); }
    }
    // the socket: a dark recess, the coloured ring, a small core
    wc.fillStyle='rgba(10,8,12,.85)';
    wc.beginPath(); wc.arc(p.x,p.y,WW.rad*0.62,0,6.2832); wc.fill();
    a=hot?1:(0.24+0.11*pls);
    wc.globalAlpha=a; wc.strokeStyle=WW.c; wc.lineWidth=Math.max(1,WW.rad*0.16);
    wc.beginPath(); wc.arc(p.x,p.y,WW.rad*0.46,0,6.2832); wc.stroke();
    wc.globalAlpha=hot?1:0.38; wc.fillStyle=WW.c;
    wc.beginPath(); wc.arc(p.x,p.y,WW.rad*(hot?0.30:0.14),0,6.2832); wc.fill();
    wc.globalAlpha=1;
  }
  return WL.length;
}
